/**
 * La lettura TRILINEARE, identica a `lookup_table_read_3D` di Cycles.
 *
 * I tre assi si saturano e si scalano a 0..15, e l'interpolazione e' annidata:
 * prima la ruvidita', poi mu, poi z. Scriverla come tre `mix` in fila darebbe lo
 * stesso numero solo perche' la griglia e' regolare — e il giorno che non lo
 * fosse, lo sarebbe in silenzio.
 */
export const GGX_GLASS_LOOKUP_SOURCE = /* wgsl */ `
fn ggxGlassAt( tab: ptr<storage, array<f32>, read>, x: i32, y: i32, z: i32 ) -> f32 {

	return (*tab)[ z * 256 + y * 16 + x ];

}
`;
export const ggxGlassAtFn = wgslFn( GGX_GLASS_LOOKUP_SOURCE, [] );

export const GGX_GLASS_READ_SOURCE = /* wgsl */ `
fn ggxGlassE( tab: ptr<storage, array<f32>, read>, rough: f32, mu: f32, z: f32 ) -> f32 {

	let fx = clamp( rough, 0.0, 1.0 ) * 15.0;
	let fy = clamp( mu, 0.0, 1.0 ) * 15.0;
	let fz = clamp( z, 0.0, 1.0 ) * 15.0;
	let ix = min( i32( fx ), 15 );
	let iy = min( i32( fy ), 15 );
	let iz = min( i32( fz ), 15 );
	let jx = min( ix + 1, 15 );
	let jy = min( iy + 1, 15 );
	let jz = min( iz + 1, 15 );
	let tx = fx - f32( ix );
	let ty = fy - f32( iy );
	let tz = fz - f32( iz );

	let c00 = mix( ggxGlassAt( tab, ix, iy, iz ), ggxGlassAt( tab, jx, iy, iz ), tx );
	let c10 = mix( ggxGlassAt( tab, ix, jy, iz ), ggxGlassAt( tab, jx, jy, iz ), tx );
	let c01 = mix( ggxGlassAt( tab, ix, iy, jz ), ggxGlassAt( tab, jx, iy, jz ), tx );
	let c11 = mix( ggxGlassAt( tab, ix, jy, jz ), ggxGlassAt( tab, jx, jy, jz ), tx );
	return mix( mix( c00, c10, ty ), mix( c01, c11, ty ), tz );

}
`;
export const ggxGlassEFn = wgslFn( GGX_GLASS_READ_SOURCE, [ ggxGlassAtFn ] );

/** La stessa lettura in JavaScript, per il gemello e le sonde. */
export function ggxGlassE( rough, mu, z ) {

	const at = ( x, y, w ) => GGX_GLASS_E[ w * 256 + y * 16 + x ];
	const sat = ( v ) => Math.min( Math.max( v, 0 ), 1 ) * 15;
	const fx = sat( rough ), fy = sat( mu ), fz = sat( z );
	const ix = Math.min( fx | 0, 15 ), iy = Math.min( fy | 0, 15 ), iz = Math.min( fz | 0, 15 );
	const jx = Math.min( ix + 1, 15 ), jy = Math.min( iy + 1, 15 ), jz = Math.min( iz + 1, 15 );
	const tx = fx - ix, ty = fy - iy, tz = fz - iz;
	const mix = ( a, b, t ) => a + ( b - a ) * t;
	const c00 = mix( at( ix, iy, iz ), at( jx, iy, iz ), tx );
	const c10 = mix( at( ix, jy, iz ), at( jx, jy, iz ), tx );
	const c01 = mix( at( ix, iy, jz ), at( jx, iy, jz ), tx );
	const c11 = mix( at( ix, jy, jz ), at( jx, jy, jz ), tx );
	return mix( mix( c00, c10, ty ), mix( c01, c11, ty ), tz );

}
